		ExecutionID:    w.ExecutionID,
		StartedAt:      w.StartedAt,
		Date:           firstRunes(w.StartedAt, 10),
		Status:         w.Status,
		Failed:         w.Status != "succeeded",
		Command:        w.Job.CommandName,
		Target:         w.Job.Target,
		Provider:       w.Job.LLM,
		RequestedModel: w.Job.Model,
		Model:          w.Result.Stats.Model,
		InputTokens:    w.Result.Stats.InputTokens,
		CachedTokens:   w.Result.Stats.CachedInputTokens,
		OutputTokens:   w.Result.Stats.OutputTokens,
		CostUSD:        w.Result.Stats.CostUSD,
		ElapsedMS:      w.Result.Stats.ElapsedMS,
		ReturnCode:     w.Result.ReturnCode,
		TimedOut:       w.Result.TimedOut,
	}, nil
}

// firstRunes returns the first n characters of s, or all of s when it is shorter.
func firstRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
